def slug(t):
    t = unicodedata.normalize("NFKD", t).encode("ascii", "ignore").decode()
    t = re.sub(r"[^a-zA-Z0-9]+", "-", t.lower()).strip("-")
    return t[:60].rstrip("-")

# Un dossier par lot (choix du 2026-10-08) : clé du lot, dossier, titre, but, démonstration de fin
LOTS = [
 ("0 (démonstrateur)", "demonstrateur", "Démonstrateur", "Montrer tôt à la direction générale ce qui se construit, sur données fictives", "Parcours de 5 minutes, en ligne (plan du démonstrateur)"),
 ("1", "lot-1-parcours-certificat", "Lot 1 — Parcours « certificat »", "Un employé complète son profil et dépose ses certificats", "Un employé au dossier complet et un au dossier incomplet, en recette"),
 ("2", "lot-2-traitement-rh", "Lot 2 — Traitement RH", "Les RH valident, pilotent et enregistrent les demandes", "File de validation et tableau de bord sur données fictives"),
 ("3", "lot-3-mise-en-service", "Lot 3 — Mise en service", "Le portail est hébergé, sécurisé et annoncé", "Test complet en recette ; guide RH ; message de lancement ; ouverture aux employés"),
 ("4", "lot-4-carriere-et-engagement", "Lot 4 — Carrière et engagement", "L'employé voit ses postes éligibles et suit ses demandes", "Un employé avec un champ périmé ; un poste publié avec indicateurs vert et orange"),
 ("Lot distinct", "lot-distinct-lettres-et-systeme-rh", "Lot distinct — Lettres et retour au système RH", "Le portail produit les lettres et renvoie les mouvements", "À préciser"),
]
LOT_DIR = {key: folder for key, folder, *_ in LOTS}

def article(p):
    return "qu'" if p[0].lower() in "aeiouéèêh" else "que "

os.makedirs(ROOT, exist_ok=True)
paths = {}
for (sid, ep, titre, lot, compl, prio, ef, rg, dec, persona, veux, afin, cas, note) in S:
    e = next(x for x in EPICS if x[0] == ep)
    d = os.path.join(ROOT, LOT_DIR[lot])
    os.makedirs(d, exist_ok=True)
    fn = f"US-{sid}-{slug(titre)}.md"
    paths[sid] = f"{LOT_DIR[lot]}/{fn}"
    lot_txt = lot if not compl else f"{lot} ({compl})"
    afin_word = "afin d'" if afin[0].lower() in "aeiouéèêh" and not afin.startswith("que") and not afin.startswith("qu") else ("afin " if afin.startswith(("que", "qu'")) else "afin de ")
    lines = [f"# US-{sid} — {titre}", "", "| | |", "|---|---|",
             f"| **Statut** | {STATUS.get(sid, 'Pas encore')} |",
             f"| **Epic** | {ep} {e[1]} |",
             f"| **Lot** | {lot_txt} |",
             f"| **Priorité** | {prio} |",
             f"| **Exigences** | {ef} |",
             f"| **Règles** | {rg} |",
             f"| **Décisions liées** | {dec} |", "",
             "## Récit", "",
             f"> En tant {article(persona)}**{persona}**, je veux {veux}, **{afin_word}{afin}**.", "",
             "## Pourquoi", "", e[3], "",
             "## Critères d'acceptation", ""]
    for i, c in enumerate(cas, 1):
        lines.append(f"- **CA-{i:02d}** {c}")
    if note:
        lines += ["", "## Notes", "", note]
    box = "[x]" if STATUS.get(sid) == "Fait" else "[ ]"
    lines += ["", "## Definition of Done", "",
              f"- {box} Chaque critère d'acceptation est couvert par un test vert",
              f"- {box} Écran vérifié sur téléphone (390 px) et sur ordinateur (1280 px), s'il y a un écran",
              f"- {box} Données fictives uniquement ; aucun salaire, aucune colonne exclue dans l'API ni les journaux",
              f"- {box} Statut mis à jour ici et dans `../README.md`", ""]
    io.open(os.path.join(d, fn), "w", encoding="utf-8").write("\n".join(lines))

# README de chaque lot : ses stories, groupées par epic
for key, folder, title, goal, demo in LOTS:
    rows = [x for x in S if x[3] == key]
    L = [f"# {title}", "", f"**But :** {goal}.", "", f"**Démonstration de fin :** {demo}.", "",
         f"{len(rows)} stories, groupées par epic. Statuts et enchaînements : [index](../README.md).", ""]
    for code, name, goal_e, why, lots in EPICS:
        group = sorted([x for x in rows if x[1] == code], key=lambda x: x[0])
        if not group: continue
        L += [f"## {code} {name}", "", goal_e, "",
              "| Story | Titre | Priorité | Complément plus tard | Statut |", "|---|---|---|---|---|"]
        for x in group:
            L.append(f"| [US-{x[0]}]({os.path.basename(paths[x[0]])}) | {x[2]} | {x[5]} | {x[4] or '—'} | {STATUS.get(x[0], 'Pas encore')} |")
        L.append("")
    io.open(os.path.join(ROOT, folder, "README.md"), "w", encoding="utf-8").write("\n".join(L))

# Index + plan par lots
